/* Mock B: 70 original questions, reviewed against the supplied Bible. Held from topic practice until the form is taken. */
(function(root){'use strict';var add=root.L.addMC;
add("mock-b-001","ch13-nodes","A 19-year-old college student with fever and fatigue has enlarged nodes in both cervical chains and in several other body regions. Which condition is associated with this generalized pattern?",
["Eagle syndrome","Infectious mononucleosis","Thyroglossal duct cyst","Branchial cleft cyst"],1,
["Eagle syndrome produces a single small, hard, tender superior jugular pseudo-node from an elongated styloid process.","","A thyroglossal duct cyst is a single midline developmental mass, not multiregional node enlargement.","A branchial cleft cyst is a single lateral neck mass, not generalized lymphadenopathy."],
"Enlarged nodes in multiple regions define generalized lymphadenopathy, and infectious mononucleosis is one of the listed causes. The other options are localized neck findings.");
add("mock-b-002","ch13-thyroid","A patient with weight loss despite increased appetite and heat intolerance has a diffusely enlarged, soft thyroid without discrete nodules. A continuous bruit is heard over the lateral lobes. Which cause is most likely?",
["Hashimoto thyroiditis","Endemic goiter","Multinodular goiter","Graves disease"],3,
["Hashimoto thyroiditis produces a firm gland rather than a soft one.","Endemic goiter causes diffuse enlargement, but a bruit with hyperthyroidism points to Graves disease or toxic multinodular goiter.","A multinodular goiter has two or more nodules, and this gland has none.",""],
"A soft, diffusely enlarged gland with a bruit and hyperthyroid symptoms fits Graves disease. Hashimoto thyroiditis also causes diffuse enlargement but the gland is firm.");
add("mock-b-003","ch13-thyroid","A single thyroid nodule is found on palpation in a patient with a history of neck irradiation. Which additional nodule characteristic would most increase concern for malignancy?",
["Hard and fixed to nearby tissue","Uniform and ovoid in shape","Freely movable over nearby tissue","Rising with the gland on swallowing"],0,
["","Uniform, ovoid structures describe benign or colloid nodules.","Benign nodules are usually not fixed to surrounding tissue.","The thyroid gland normally rises with swallowing, so this does not separate benign from malignant."],
"Hardness and fixation to surrounding tissues are listed malignancy risk factors for a single nodule. Benign colloid nodules are uniform, ovoid, and usually not fixed.");
add("mock-b-004","ch14-acuity","With glasses, a patient's visual acuity is 20/60 in the right eye and 20/250 in the left eye. Which classification applies?",
["Visual impairment without legal blindness","Legal blindness based on the left eye","Normal corrected visual acuity","Legal blindness based on both eyes"],0,
["","Both definitions use corrected acuity in the better eye, not the worse eye.","Corrected acuity of 20/40 or worse in the better eye meets the definition of visual impairment.","The better eye is 20/60, which is better than the 20/200 cutoff for legal blindness."],
"Classification uses corrected acuity in the better eye, here 20/60. That is 20/40 or worse (visual impairment) but not 20/200 or worse (legal blindness).");
add("mock-b-005","ch14-cornea","Through a dilated pupil, the examiner sees spoke-like shadows that appear black against the red reflex when viewed with the ophthalmoscope. Which finding is this?",
["Nuclear cataract","Corneal scar","Corneal arcus","Peripheral cataract"],3,
["A nuclear cataract appears as a central gray opacity surrounded by a black rim when the pupil is dilated.","A corneal scar is a superficial grayish-white opacity in the cornea, not a lens opacity seen through the pupil.","Corneal arcus is a grayish-white arc near the edge of the cornea.",""],
"Spoke-like shadows, black against red with an ophthalmoscope, describe a peripheral cataract. A nuclear cataract is a central gray opacity instead.");
add("mock-b-006","ch14-near","During testing of the near reaction, the patient alternates gaze between a pencil 10 cm away and the far wall. Which component of the near reaction cannot be seen by the examiner?",
["Pupillary constriction","Accommodation of the lens","Convergence of the eyes","Consensual pupil constriction"],1,
["The examiner watches for pupillary constriction with near effort, so it is visible.","","The examiner watches for convergence of the eyes, so it is visible.","Consensual constriction belongs to the light reaction, not the near reaction."],
"Accommodation, the increased lens convexity that brings a near object into focus, occurs behind the iris and is not visible. Pupillary constriction and convergence are the observable parts.");
add("mock-b-007","ch14-redpain","A patient's red eye shows redness concentrated around the limbus, a small irregular pupil, no discharge, and deep aching pain with photophobia. Which interpretation and action is most appropriate?",
["Conjunctivitis that is highly contagious","Subconjunctival hemorrhage that resolves","Acute iritis requiring prompt referral","Dry-eye syndrome relieved by artificial tears"],2,
["Conjunctivitis causes mild discomfort, peripheral redness, and a normal pupil.","Subconjunctival hemorrhage is painless with a sharply demarcated red area and a normal pupil.","","Dry-eye syndrome causes a gritty sensation and does not produce a small, irregular pupil."],
"Limbal ciliary injection, a small irregular pupil, and deep aching pain with photophobia fit acute iritis, which is associated with systemic disease and needs prompt referral. Conjunctivitis spares the pupil and causes only mild discomfort.");
add("mock-b-008","ch14-redpain","A patient has a nontender, painless eyelid nodule that developed over several weeks and points toward the inside of the lid rather than the lid margin. Which is most likely?",
["Stye (hordeolum)","Xanthelasma","Chalazion","Pinguecula"],2,
["A stye is a painful, tender, red infection at the lid margin.","Xanthelasma is a yellowish cholesterol plaque along the nasal portion of the eyelids.","","A pinguecula is a yellowish nodule of the bulbar conjunctiva, not the eyelid."],
"A subacute, nontender nodule from a blocked meibomian gland that points inside the lid is a chalazion. A stye differs by being painful and tender at the lid margin.");
add("mock-b-009","ch15-hearing","During a whispered voice test with the examiner standing behind the seated patient, the patient correctly repeats only 2 of 6 whispered numbers and letters in the left ear. What is the appropriate next step?",
["Document normal hearing in that ear","Repeat the same combination until correct","Repeat while facing the patient","Further testing with audiometry"],3,
["Passing requires repeating at least 3 of 6 items correctly; 2 of 6 is a failure.","Repeats use a different combination to exclude a learning effect, and 2 of 6 already meets failure criteria.","The examiner stands behind the patient specifically to prevent lip reading.",""],
"Repeating fewer than 3 of 6 items is a failed whispered voice test, which calls for further testing with audiometry. Standing behind the patient is part of correct technique because it prevents lip reading, so facing the patient would invalidate the test.");
add("mock-b-010","ch15-hearing","A patient has hearing loss of equal severity in both ears. The examiner places a vibrating tuning fork on the vertex, and the patient hears it equally in both ears. What can be concluded from this Weber result?",
["Bilateral conductive loss","No conclusion about type of loss","Bilateral sensorineural loss","Normal hearing in both ears"],1,
["Bilateral conductive deficits do not lateralize, so a midline Weber cannot confirm a conductive cause.","","Bilateral sensorineural deficits also do not lateralize, so a midline Weber cannot confirm a sensorineural cause.","The patient has known bilateral hearing loss; a midline Weber does not show that hearing is normal."],
"The Weber test is used only in unilateral hearing loss because bilateral conductive or sensorineural deficits will not lateralize. A midline result here therefore cannot tell conductive from sensorineural loss.");
add("mock-b-011","ch15-tinnitus","A patient with new tinnitus brings a list of recent medications. Which drug is most associated with permanent, rather than temporary, hearing loss and tinnitus?",
["Aminoglycoside antibiotic","Aspirin","Loop diuretic","Quinine"],0,
["","Aspirin is listed as a cause of temporary tinnitus.","Loop diuretics are listed as a cause of temporary tinnitus.","Quinines are listed as a cause of temporary tinnitus."],
"Aminoglycosides and some chemotherapy agents such as cisplatin are linked to permanent hearing loss and tinnitus. Aspirin, NSAIDs, loop diuretics, and quinines produce temporary tinnitus.");
add("mock-b-012","ch15-vertigo","A patient has had constant vertigo with nausea, vomiting, and nystagmus for 5 days. It began suddenly and is the first episode. There is new hearing loss in the right ear with tinnitus, but no ear pressure or fullness. Which diagnosis fits best?",
["Vestibular neuronitis","Meniere disease","Acute labyrinthitis","Central vertigo"],2,
["Vestibular neuronitis has a similar time course but does not affect hearing and lacks tinnitus.","Meniere disease is recurrent, with attacks of several hours to about a day, and includes pressure or fullness in the ear.","","Central vertigo does not affect hearing and usually comes with brainstem deficits."],
"Sudden vertigo lasting days with unilateral sensorineural hearing loss and possible tinnitus fits acute labyrinthitis. Vestibular neuronitis shares the time course but spares hearing, and Meniere disease would be recurrent with ear pressure or fullness.");
add("mock-b-013","ch16-oral","A patient has a dull red throat with a gray exudate forming a pseudomembrane over the uvula, pharynx, and tongue. The airway is at risk of obstruction. Which diagnosis is most likely?",
["Exudative tonsillitis","Thrush (candidiasis)","Pharyngitis","Diphtheria"],3,
["Exudative tonsillitis shows thick white exudates on the tonsils of a red throat, not a gray membrane spreading to the uvula and tongue.","Thrush forms cream-colored or bluish-white patches rather than a gray pseudomembrane on a dull red throat.","Pharyngitis shows a reddened throat without exudate.",""],
"Diphtheria produces a dull red throat with a gray exudate (pseudomembrane) on the uvula, pharynx, and tongue and can obstruct the airway, so prompt diagnosis may be life-saving. Exudative tonsillitis, the closest competitor, has white exudates confined to the tonsils.");
add("mock-b-014","ch16-oral","A patient with HIV has whitish, raised, asymptomatic plaques with a feathery, corrugated pattern along the sides of the tongue. The plaques cannot be scraped off. Which finding is this?",
["Candidiasis","Oral hairy leukoplakia","Geographic tongue","Mucous patch of syphilis"],1,
["Candidal white coating can be scraped off, leaving a raw red surface.","","Geographic tongue shows smooth red areas denuded of papillae in a changing map-like pattern.","A mucous patch is a slightly raised oval lesion covered by a grayish membrane, not feathery lateral tongue plaques."],
"Oral hairy leukoplakia forms whitish raised plaques with a feathery or corrugated pattern, most often on the sides of the tongue, is caused by Epstein-Barr virus, and is seen in HIV infection. Unlike candidiasis, it cannot be scraped off.");
add("mock-b-015","ch17-advent","After a rapid ascent while scuba diving, a patient has severe central chest pain. With the patient in the left lateral position, a series of precordial crackles is heard in time with the heartbeat rather than with breathing. Which finding is this?",
["Pleural rub","Coarse crackles","Mediastinal crunch","Fine crackles"],2,
["A pleural rub follows respiration, heard in inspiration and expiration, not the heartbeat.","Coarse crackles follow the respiratory cycle, from early inspiration through expiration.","","Fine crackles occur from mid to late inspiration and follow breathing, not the heartbeat."],
"A mediastinal crunch (Hamman sign) is a series of precordial crackles synchronous with the heartbeat, best heard in the left lateral position, from air in the mediastinum; rapid ascent from scuba diving is a reported cause. The other sounds are tied to respiration.");
add("mock-b-016","ch17-advent","During a severe asthma attack, a patient's loud wheezes become barely audible equally over both sides of the chest while air movement is minimal. What is the best interpretation?",
["Bronchospasm is resolving","Airways are narrowing further","Secretions have been cleared","Air has entered the pleural space"],1,
["Resolving bronchospasm would improve air movement, not leave it minimal.","","Clearing of secretions explains rhonchi that disappear with coughing, not fading wheezes with poor air movement.","Pleural air decreases breath sounds over the affected side only, not symmetrically over both lungs."],
"As airways narrow further, wheezes become less audible, ending in the silent chest of severe asthma that needs immediate intervention. Mistaking the quieter chest for resolving bronchospasm is the key trap.");
add("mock-b-017","ch17-breath","Which timing pattern characterizes the bronchial breath sounds normally heard over the manubrium?",
["Inspiratory sounds last longer than expiratory sounds","Inspiratory and expiratory sounds are almost equal","Expiratory sounds last longer than inspiratory sounds","Continuous through inspiration, fading early in expiration"],2,
["A longer inspiratory phase describes vesicular breath sounds.","Nearly equal phases describe bronchovesicular and tracheal breath sounds.","","Sound continuous through inspiration that fades one third of the way through expiration describes vesicular breath sounds."],
"Bronchial breath sounds are loud, with a short silence between phases and an expiratory phase longer than the inspiratory one. A longer inspiratory phase is the vesicular pattern.");
add("mock-b-018","ch17-breath","While palpating tactile fremitus in a healthy adult who repeats \"ninety-nine,\" where should the examiner expect the vibrations to be most prominent?",
["Interscapular area","Lower posterior lung fields","Over the precordium","Just below the diaphragm"],0,
["","Fremitus is normally less prominent in the lower lung fields than in the interscapular area.","Fremitus is usually decreased or absent over the precordium.","Fremitus disappears below the diaphragm."],
"Normal tactile fremitus is more prominent in the interscapular area than in the lower lung fields and disappears below the diaphragm. The lower fields are the closest competitor but normally transmit less vibration.");
add("mock-b-019","ch17-chestdis","A 68-year-old former smoker has diffusely hyper-resonant percussion, a midline trachea, decreased breath sounds with delayed expiration, decreased fremitus, and no adventitious sounds. Which condition best fits?",
["Asthma","Chronic bronchitis","Pneumothorax","COPD"],3,
["In asthma, breath sounds are often obscured by wheezes, and wheezes are the expected adventitious sound.","Chronic bronchitis is resonant with vesicular breath sounds and normal fremitus.","Pneumothorax is hyper-resonant over the pleural air on one side, not diffusely.",""],
"COPD is diffusely hyper-resonant with decreased to absent breath sounds, delayed expiration, decreased fremitus, and possibly no adventitious sounds. Asthma can also be hyper-resonant, but its breath sounds are typically obscured by wheezes.");
add("mock-b-020","ch17-chestdis","A patient with a long-standing productive cough has resonant percussion, vesicular breath sounds, normal fremitus, and scattered coarse crackles in early inspiration and expiration. Which condition from Table 17-8 fits best?",
["Chronic bronchitis","Left-sided heart failure","Lobar pneumonia","Pleural effusion"],0,
["","Left-sided heart failure produces late inspiratory crackles in dependent portions of the lungs.","Lobar pneumonia is dull with bronchial breath sounds and increased fremitus over the involved area.","Pleural effusion is dull to flat with decreased to absent breath sounds and fremitus."],
"Chronic bronchitis keeps a resonant note, vesicular sounds, and normal fremitus, with possible scattered coarse crackles in early inspiration and expiration. Left-sided heart failure shares the resonant, vesicular pattern but its crackles are late inspiratory and dependent.");
add("mock-b-021","ch17-cough","A 62-year-old man has had a dry cough for 10 weeks. His chest examination is unremarkable, and he started a new daily medication shortly before the cough began. Which medication class is most likely to be responsible?",
["ACE inhibitor","Inhaled bronchodilator","Oral corticosteroid","Anticoagulant"],0,
["","Bronchodilators may help alleviate cough rather than cause it.","Corticosteroids may help alleviate cough rather than cause it.","Anticoagulants are asked about because they raise bleeding risk, including hemoptysis, not because they cause cough."],
"Angiotensin-converting enzyme inhibitors are a listed medication cause of cough. Bronchodilators and corticosteroids are named as agents that may relieve cough instead.");
add("mock-b-022","ch17-percussion","An examiner marks the level of dullness at full expiration and again at full inspiration on the posterior chest of a healthy adult. Which distance between the two levels is within the typical range?",
["1 cm","4 cm","7 cm","9 cm"],1,
["1 cm is below the typical excursion of 3 to 5.5 cm.","","7 cm is above the typical excursion of 3 to 5.5 cm.","9 cm is well above the typical excursion of 3 to 5.5 cm."],
"Diaphragmatic excursion is the distance between the dullness levels on full expiration and full inspiration and is typically 3 to 5.5 cm. Only 4 cm falls in that range.");
add("mock-b-023","ch17-thorax","On inspection, a young adult's sternum is displaced anteriorly, increasing the AP diameter, and the costal cartilages beside it are depressed. Which deformity is this?",
["Funnel chest (pectus excavatum)","Barrel chest","Thoracic kyphoscoliosis","Pigeon chest (pectus carinatum)"],3,
["Funnel chest is a depression of the lower sternum, not an anterior displacement.","Barrel chest increases the AP diameter without a protruding sternum and depressed adjacent cartilages; it accompanies aging and COPD.","Kyphoscoliosis is abnormal spinal curvature and vertebral rotation that deforms the chest.",""],
"Pigeon chest (pectus carinatum) is an anteriorly displaced sternum with depressed adjacent costal cartilages, which increases the AP diameter. Barrel chest also increases the AP diameter but without the protruding sternum.");
add("mock-b-024","ch18-grade","A diastolic murmur begins shortly after S2 and occupies more than half of diastole but not all of it. An opening snap is also present. Which grade is appropriate?",
["Grade 1/4","Grade 2/4","Grade 3/4","Grade 4/4"],2,
["Grade 1/4 is a short early diastolic murmur heard immediately after S2.","Grade 2/4 is only slightly longer than grade 1 and does not occupy more than half of diastole.","","Grade 4/4 is pan-diastolic, occupying all of diastole."],
"Diastolic murmurs are graded by duration: grade 3/4 is a longer mid-diastolic murmur occupying more than half of diastole and may have an associated opening snap. Grade 4/4 would require the murmur to fill all of diastole.");
add("mock-b-025","ch18-heave","While palpating the precordium with a flat palm, the examiner feels a sustained impulse that rhythmically lifts the hand. What most commonly produces this finding?",
["Turbulent flow across a narrowed valve","Inflammation of the pericardial sac","An enlarged right or left ventricle","Brief early LV contact with the chest wall"],2,
["Turbulent flow produces the buzzing vibration of a thrill, not a sustained lift.","Pericardial inflammation produces a scratchy, grating friction rub heard on auscultation.","","The normal apical impulse is a brief early pulsation, a nonsustained tap rather than a sustained lift."],
"Heaves are sustained impulses that rhythmically lift the examiner's fingers and are usually produced by an enlarged right or left ventricle, occasionally by a ventricular aneurysm. A thrill, by contrast, is a buzzing sensation from turbulent flow.");
add("mock-b-026","ch18-htn","A seated patient's blood pressure is measured with the unsupported arm hanging at the side, well below heart level. How will this affect the reading?",
["Lower than the true value","Unchanged if the cuff is correctly sized","Lower systolic with unchanged diastolic","Higher than the true value"],3,
["Readings are lower when the arm is positioned above heart level, not below it.","A correctly sized cuff does not offset the error from arm position.","An arm below heart level raises the recordings; it does not lower the systolic value.",""],
"The arm should be supported at heart level, around the fourth intercostal space at the sternum. At lower arm levels the BP recordings will be higher, and at higher arm levels they will be lower.");
add("mock-b-027","ch18-jvp","A patient with ankle edema and dyspnea is examined with the head of the bed at 45 degrees. The highest point of right internal jugular pulsation is 6 cm vertically above the sternal angle. How should this be interpreted?",
["Normal, because the head was raised above 30 degrees","Elevated, consistent with heart failure","Low, consistent with volume loss","Invalid, because JVP must be measured at 30 degrees"],1,
["The height above the sternal angle stays similar across positions, so raising the head does not normalize a reading above 3 cm.","","JVP falls with blood loss, but 6 cm above the sternal angle exceeds the 3 cm upper limit.","The bed may be raised or lowered until the meniscus is visible; the measured height is similar in all positions."],
"A JVP more than 3 cm above the sternal angle (more than 8 cm above the right atrium) is elevated and strongly associated with acute and chronic heart failure. The head of the bed can be adjusted as needed because the height above the sternal angle remains similar across positions.");
add("mock-b-028","ch18-maneuvers","A 28-year-old has a midsystolic click followed by a late systolic murmur. The examiner listens with the patient squatting and then has the patient stand. What change is expected on standing?",
["The click and murmur move closer to S1","The click and murmur move closer to S2","The click and murmur disappear completely","The click and murmur keep the same timing"],0,
["","Squatting (and Valsalva release) delays the click and murmur toward S2; standing does the opposite.","Standing changes the timing of the prolapse findings rather than abolishing them.","Mitral valve prolapse findings are position dependent, so their timing shifts with standing."],
"In mitral valve prolapse, standing (and Valsalva strain) advances the click and murmur closer to S1, while squatting (and Valsalva release) delays them. This is why multiple positions, including squatting and standing, are recommended.");
add("mock-b-029","ch18-maneuvers","Using the bell lightly at the apex, the examiner hears a dull, low-pitched sound early in diastole. When the bell is pressed firmly against the skin, the sound disappears. Which sound is most likely?",
["Opening snap","Early systolic ejection sound","Midsystolic click","Third heart sound (S3)"],3,
["An opening snap is high pitched and persists or gets louder with firm bell pressure.","An ejection sound is high pitched, occurs just after S1, and persists with firm pressure.","A midsystolic click is high pitched, occurs in systole, and persists with firm pressure.",""],
"Firm pressure makes the bell act like a diaphragm, so low-pitched sounds such as S3 and S4 may disappear while high-pitched sounds persist. An opening snap also occurs early in diastole but is high pitched and would persist or get louder.");
add("mock-b-030","ch18-metabolic","A 50-year-old has elevated blood pressure and a reduced HDL cholesterol level. Which additional finding would establish metabolic syndrome?",
["Elevated LDL cholesterol","Elevated fasting plasma glucose","Family history of premature CVD","Current cigarette smoking"],1,
["LDL cholesterol is not one of the five metabolic syndrome criteria; reduced HDL is.","","Family history of premature CVD is a screened CVD risk factor but not a metabolic syndrome criterion.","Tobacco use is a modifiable CVD risk factor but not one of the five criteria."],
"Metabolic syndrome requires any three of five factors: elevated waist circumference, elevated triglycerides, reduced HDL, elevated BP, and elevated fasting plasma glucose. Adding elevated fasting glucose gives this patient three criteria; LDL, family history, and smoking are CVD risk factors but not criteria.");
add("mock-b-031","ch18-murmurtiming","A 60-year-old has a soft, high-pitched, blowing murmur that begins immediately after S2 with no gap and fades before the next S1. Which valve lesion does this timing most suggest?",
["Mitral stenosis","Aortic regurgitation","Aortic stenosis","Mitral regurgitation"],1,
["Mitral stenosis causes a low-pitched mid- to late diastolic rumble rather than a high-pitched murmur starting right at S2.","","Aortic stenosis produces a midsystolic murmur between S1 and S2, not a diastolic murmur.","Mitral regurgitation produces a holosystolic murmur from S1 to S2, not a diastolic murmur."],
"An early diastolic murmur starts immediately after S2 and fades before S1; early decrescendo diastolic murmurs signify regurgitation through an incompetent semilunar valve, usually the aortic. Mitral stenosis is also diastolic but is a low-pitched mid- to late diastolic rumble.");
add("mock-b-032","ch18-s1s2","A 55-year-old with progressive exertional dyspnea has a split S2 in which P2 is louder than A2. Which condition should the examiner suspect?",
["Pulmonary hypertension","Systemic hypertension","Calcific aortic stenosis","Increased AP chest diameter"],0,
["","Systemic hypertension increases the intensity of A2, not P2.","Calcific aortic stenosis decreases or abolishes A2 rather than accentuating P2.","An increased AP diameter usually makes P2 softer or absent."],
"A2 is normally the louder component; when P2 is equal to or louder than A2, suspect pulmonary hypertension. Systemic hypertension accentuates the aortic component instead.");
add("mock-b-033","ch18-systdiast","A 20-year-old has a harsh, high-pitched holosystolic murmur at the left third to fifth intercostal spaces. It is very loud with a thrill, and S2 is obscured. Which condition is most likely?",
["Mitral regurgitation","Tricuspid regurgitation","Ventricular septal defect","Hypertrophic cardiomyopathy"],2,
["Mitral regurgitation is a blowing murmur loudest at the apex that radiates to the left axilla.","Tricuspid regurgitation is a blowing, medium-pitched murmur; a harsh, very loud murmur with a thrill that obscures S2 fits a VSD.","","Hypertrophic cardiomyopathy appears among the midsystolic murmurs, not the holosystolic ones, at the left third and fourth interspaces."],
"Table 18-10 describes the VSD murmur as a harsh, high-pitched holosystolic murmur at the left third to fifth interspaces, often very loud with a thrill, which may obscure S2. Mitral regurgitation is also holosystolic but is blowing, apical, and radiates to the axilla.");
add("mock-b-034","ch18-valves","During a sports physical, a soft murmur is heard best in the left second intercostal space close to the sternum. Which valve is the typical origin of sounds heard best at this site?",
["Aortic","Tricuspid","Mitral","Pulmonic"],3,
["Aortic valve sounds are typically heard at the right second intercostal space.","Tricuspid sounds are at the left fourth interspace at or near the lower left sternal border.","Mitral sounds are at the left fifth interspace at the midclavicular line around the apex.",""],
"Box 18-2 places pulmonic valve sounds at the left second and third intercostal spaces close to the sternum. The aortic area is the mirror-image site on the right, at the right second intercostal space.");
add("mock-b-035","ch19-abi","Doppler pressures in a patient's left leg are 65 mm Hg at the dorsalis pedis and 75 mm Hg at the posterior tibial artery. The brachial systolic pressure is 140 mm Hg. Which left ABI value and interpretation are correct?",
["0.46, in the severe PAD range","1.87, in the noncompressible vessel range","0.54, in the severe PAD range","0.54, in the PAD range but not severe"],3,
["0.46 comes from using the lower dorsalis pedis pressure, but the ABI uses the higher of the two ankle pressures.","1.87 comes from dividing brachial by ankle pressure; the ABI is the ankle pressure divided by the brachial pressure.","Severe PAD is suggested only by values below 0.5, and 0.54 is above that threshold.",""],
"The ABI is the higher ankle pressure divided by the brachial systolic pressure: 75/140 = 0.54. A value below 0.90 is diagnostic of PAD, and only values below 0.5 suggest severe PAD, so 0.54 is PAD but not severe. Using the lower dorsalis pedis pressure (0.46) or inverting the ratio (1.87) gives a wrong result.");
add("mock-b-036","ch19-allen","During an Allen test, the examiner has just confirmed that the ulnar artery is patent. How should the examiner now evaluate the radial artery?",
["Keep compressing the radial artery and release the ulnar artery","Release both arteries together and time the palmar flush","Keep compressing the ulnar artery and release the radial artery","Have the patient fully extend the hand, then release the radial artery"],2,
["Holding the radial artery and releasing the ulnar artery is the ulnar step that was already completed.","Releasing both arteries at once cannot show which artery restored the palmar color.","","Fully extending the hand can itself induce pallor and produce a falsely positive result."],
"The Allen test evaluates both arteries: after the ulnar step, the examiner maintains compression on the ulnar artery and releases the radial artery, and a patent radial artery restores palmar color. Keeping the hand relaxed and slightly flexed avoids false pallor from full extension.");
add("mock-b-037","ch19-arteryvein","A patient has bilateral swelling of the feet and toes. The swelling is hard and nonpitting, the skin is markedly thickened, and there is no brown pigmentation. Which type of peripheral edema is most likely?",
["Lymphedema","Chronic venous insufficiency","Pitting edema from heart failure","Iliofemoral deep vein thrombosis"],0,
["","Venous insufficiency edema is soft and pitting, with brownish pigmentation common near the ankle.","Edema from heart failure pits after thumb pressure on the feet.","Iliofemoral DVT causes a painful, pale, swollen leg with groin tenderness, not bilateral hard nonpitting edema."],
"Table 19-1 describes lymphedema as edema that becomes indurated, hard, and nonpitting with markedly thickened skin, common in both feet and toes, and with no pigmentation. Chronic venous insufficiency, the closest competitor, is soft and pitting with brownish pigmentation.");
add("mock-b-038","ch19-claud","A 72-year-old patient reports sharp leg pain that worsens with prolonged standing or walking and is relieved only by sitting down or bending forward. Which cause is most likely?",
["Intermittent claudication from PAD","Chronic venous insufficiency","Neurogenic claudication from spinal stenosis","Deep vein thrombosis"],2,
["PAD claudication is cramping or aching and resolves within minutes of rest, without needing to sit or bend forward.","Venous insufficiency causes leg swelling and pain, not position-dependent relief by forward bending.","","DVT causes pain and swelling in the affected leg that is not relieved by forward bending or sitting."],
"Neurogenic claudication from lumbar spinal stenosis is distinguished by pain that worsens with prolonged standing or walking but is relieved by forward bending or sitting, and a sharp or stabbing quality also points to spinal stenosis. Vascular claudication is cramping and eases with rest alone.");
add("mock-b-039","ch19-pad","A 68-year-old patient who smokes and has hypertension but no leg symptoms asks whether an ankle-brachial index should be done to screen for PAD. Which statement reflects the screening guidance in the chapter?",
["The AHA considers ABI screening reasonable when risk factors exist","The USPSTF recommends ABI screening when risk factors exist","A normal ABI rules out PAD because the test is highly sensitive","The ABI is too unreliable to perform in the office setting"],0,
["","The USPSTF does not advocate PAD screening; it issued an I statement because the evidence is insufficient.","The sensitivity of an abnormal ABI is low (15% to 20%), so a normal result does not rule out PAD.","The chapter describes the ABI as reliable, reproducible, and easy to perform in the office."],
"The USPSTF does not advocate PAD screening because the evidence is insufficient (I statement), but the AHA suggests that ABI screening in patients with risk factors such as smoking and hypertension is reasonable. The ABI has low sensitivity but 99% specificity, so a normal value does not exclude PAD.");
add("mock-b-040","ch19-pulses","With the patient supine and the knee somewhat flexed, the examiner presses the fingertips of both hands deeply into the popliteal fossa but cannot feel a pulse. What should the examiner do next?",
["Record the popliteal pulse as 0 on the grading scale","Repeat with the patient prone and the knee flexed to 90 degrees","Use toe capillary refill time in place of the pulse","Straighten the knee fully and palpate more lightly"],1,
["The popliteal pulse is deep and hard to find, so it should not be graded absent before the prone technique is tried.","","Capillary refill time in the digits has low sensitivity and specificity and is not diagnostically helpful.","The technique calls for a flexed, relaxed knee and deep pressure, not an extended knee and light touch."],
"The popliteal pulse is deeper and more diffuse than other pulses, so if it cannot be felt supine, Bates directs the examiner to try with the patient prone, the knee flexed to about 90 degrees, and both thumbs pressed deeply into the fossa. Recording it as absent before this step would be premature.");
add("mock-b-041","ch19-ulcers","An ulcer is found on the foot of a patient with long-standing diabetes. Which accompanying finding would most support a neuropathic cause for the ulcer?",
["Dusky rubor of the foot on dependency","Stasis dermatitis with scaling and pruritus","Cyanosis of the foot when dependent","Absent ankle jerks and decreased sensation"],3,
["Dusky rubor on dependency accompanies arterial insufficiency ulcers.","Stasis dermatitis accompanies chronic venous insufficiency ulcers.","Cyanosis of the dependent foot is an associated finding of venous ulcers.",""],
"Table 19-4 lists decreased sensation and absent ankle jerks as the associated signs of a neuropathic ulcer. Dusky rubor on dependency points to arterial insufficiency, and stasis dermatitis or dependent cyanosis point to venous insufficiency.");
add("mock-b-042","ch21-acute","A patient's periumbilical pain migrated to the right lower quadrant and steadily worsened over 18 hours. The patient now reports that the pain has suddenly eased. What should the examiner suspect?",
["Spontaneous resolution of appendicitis","Progression from visceral to parietal pain","Referred pain from the biliary tree","Perforation of the appendix"],3,
["Appendicitis pain continues to worsen until intervention, so sudden easing is not reassuring resolution.","The shift to parietal pain makes pain sharper and more localized, not relieved.","Biliary referred pain appears in the right scapular region, not as relief of right lower quadrant pain.",""],
"Appendicitis pain typically worsens until treatment, so temporary subsidence should raise concern for perforation. The visceral to parietal shift explains the migration to the right lower quadrant, not a sudden decrease in pain.");
add("mock-b-043","ch21-acute","During light palpation, a patient's abdominal muscles stay tense even after the hips are flexed, the patient mouth-breathes with the jaw open, and palpation is timed with exhalation. What does this finding most suggest?",
["Anxiety-related voluntary guarding","Peritoneal inflammation","Abdominal wall tenderness","Visceral tenderness from deep palpation"],1,
["Voluntary guarding usually diminishes with these relaxation techniques.","","Abdominal wall tenderness is identified by persistence when the head and shoulders are raised, not by rigidity despite relaxation.","Visceral tenderness is dull and occurs without muscular rigidity."],
"Guarding that does not decrease with relaxation techniques is involuntary and often indicates peritoneal irritation. Voluntary guarding from anxiety usually lessens with hip flexion, mouth-breathing, or exhalation.");
add("mock-b-044","ch21-aorta","A 70-year-old smoker has an aortic width that feels normal on deep abdominal palpation. Which statement about this result is most accurate?",
["A normal palpated width rules out an aneurysm","Palpation is most sensitive for aneurysms under 5 cm","Aortic width assessment is reserved for patients under 50","Palpation can miss smaller aneurysms that imaging detects"],3,
["Palpation sensitivity varies with aneurysm size, so a normal result does not exclude an aneurysm.","Sensitivity increases with size; aneurysms of 5 cm or more are the ones more likely detected.","Width assessment is recommended for adults older than 50, smokers, and those with vascular risk.",""],
"Palpation detects larger aneurysms more reliably, and ultrasound or CT is more reliable for smaller ones. A normal palpated width therefore does not exclude a small aneurysm.");
add("mock-b-045","ch21-hepatomeg","A patient has an enlarged liver whose edge is smooth and tender to palpation. Which condition does this finding most suggest?",
["Hepatitis","Cirrhosis","Hepatocellular carcinoma","Riedel lobe"],0,
["","Cirrhosis typically produces an enlarged liver with a firm, nontender edge.","Hepatocellular carcinoma produces a firm or hard liver with an irregular edge or nodules.","A Riedel lobe is a shape variation, not true enlargement, and does not imply tenderness."],
"A smooth, tender enlarged liver edge suggests inflammation, as in hepatitis, or venous congestion. Cirrhosis can also enlarge the liver, but its edge is firm and nontender.");
add("mock-b-046","ch21-ibs","For the past 6 months, a patient has had fewer than 3 spontaneous bowel movements per week and strains during more than a quarter of defecations. The patient denies abdominal pain. Which Rome IV disorder best fits?",
["Irritable bowel syndrome","Functional constipation","Functional diarrhea","Functional abdominal bloating"],1,
["Irritable bowel syndrome requires recurrent abdominal pain at least weekly, which this patient denies.","","Functional diarrhea involves loose or watery stools, not infrequent stools with straining.","Functional abdominal bloating involves recurrent bloating or distention, which is not described."],
"Two or more features such as straining in over 25% of defecations and fewer than 3 spontaneous bowel movements weekly meet Rome IV functional constipation. Irritable bowel syndrome can include constipation but requires recurrent abdominal pain.");
add("mock-b-047","ch21-sequence","A patient has a protuberant abdomen that is tympanitic to percussion throughout, including the flanks. Which cause is most consistent with this finding?",
["Ascites","Large ovarian tumor","Intestinal obstruction","Distended urinary bladder"],2,
["Ascites produces bulging flanks that are dull to percussion.","A large solid pelvic tumor is dull to percussion with bowel displaced to the periphery.","","A markedly distended bladder is dull and can be mistaken for a pelvic tumor."],
"Diffuse tympany over a protuberant abdomen reflects gas and suggests intestinal obstruction or paralytic ileus. Ascites would instead produce dullness in the dependent flanks.");
add("mock-b-048","ch21-special","A patient with right lower quadrant pain is turned onto the left side, and the examiner extends the right thigh at the hip. Abdominal pain increases. What does this positive finding most suggest?",
["Inflamed appendix within the pelvis","Acute inflammation of the gallbladder","Inflamed retrocecal appendix","Inflammation of the fallopian tubes"],2,
["A pelvic appendix is suggested by a positive obturator sign, which uses internal rotation of the flexed hip.","Gallbladder inflammation is assessed with the Murphy sign in the right upper quadrant.","","Salpingitis tenderness is usually bilateral just above the inguinal ligaments with cervical motion pain."],
"Extending the right thigh stretches the psoas muscle; increased pain is a positive psoas sign from an inflamed retrocecal appendix. The obturator sign, not the psoas sign, points to an appendix located in the pelvis.");
add("mock-b-049","ch21-special","A firm mass is palpated near the umbilicus. When the patient raises the head and shoulders to tighten the abdominal muscles, the mass remains easily palpable. Where is the mass most likely located?",
["In the abdominal wall","Inside the abdominal cavity","In the retroperitoneum","Deep in the pelvic cavity"],0,
["","An intra-abdominal mass is obscured by muscular contraction.","Retroperitoneal structures lie behind the cavity and would be obscured even more by contracted muscles.","A deep pelvic mass would be hidden behind the tightened abdominal muscles."],
"Tightening the abdominal muscles hides intra-abdominal masses, while a mass in the abdominal wall stays palpable. A mass inside the cavity would become harder to feel with this maneuver.");
add("mock-b-050","ch27-clonus","Right after jogging to the clinic, an anxious patient has two or three clonic beats when the ankle is sharply dorsiflexed, after which the foot stays still in dorsiflexion. Which interpretation fits best?",
["Sustained clonus pointing to corticospinal disease","A benign response to tension or recent exercise","A lower motor neuron sign of nerve root disease","Rigidity from disease of the basal ganglia"],1,
["The beats stopped after two or three, so this is not sustained clonus.","","Lower motor neuron lesions cause hyporeflexia, atrophy, and fasciculations, not clonic beats.","Rigidity is constant increased tone through the range of motion, not a few rhythmic beats."],
"A few clonic beats may occur if the patient is tense or has recently exercised; normally the ankle then stays held in dorsiflexion. Only sustained clonus points to corticospinal tract disease.");
add("mock-b-051","ch27-cns-pns","A 30-year-old has trouble climbing stairs and combing their hair. Weakness is greater in the hips and shoulders than the hands and feet, does not worsen with repeated use, and there are no fasciculations. Sensation is intact. Which lesion location best fits?",
["Neuromuscular junction","Peripheral polyneuropathy","Muscle","Anterior horn cell"],2,
["Neuromuscular junction disease causes fatigability more than weakness, which this patient lacks.","Polyneuropathy causes weakness more distal than proximal with stocking-glove sensory loss.","","Anterior horn cell disease causes segmental atrophy with fasciculations."],
"Table 27-1 describes muscle disease as weakness usually more proximal than distal, no fasciculations, and intact sensation, as in muscular dystrophy. Neuromuscular junction disease also spares sensation but shows fatigability.");
add("mock-b-052","ch27-coma-pupils","After resuscitation from cardiac arrest, a comatose patient has both pupils dilated and fixed to light. No atropine-like drugs were given. Which explanation does Table 27-16 favor?",
["Hemorrhage in the pons","Temporal lobe herniation","Sympathetic agonist such as cocaine","Severe anoxia"],3,
["A pontine hemorrhage causes pinpoint pupils, not dilated ones.","Temporal lobe herniation compressing CN III causes one fixed, dilated pupil, not two.","Cocaine and similar agonists cause large pupils that remain reactive to light.",""],
"Table 27-16 attributes bilaterally fixed and dilated pupils to severe anoxia with sympathomimetic effects, as after cardiac arrest. Herniation fixes and dilates only one pupil, and large pupils from cocaine or similar agonists still react to light.");
add("mock-b-053","ch27-conscious","A patient with a head injury opens the eyes when their name is called, reaches up to push away the examiner's hand during sternal pressure, and converses but is disoriented. What is the Glasgow Coma Scale total?",
["12","10","11","13"],0,
["","A total of 10 would score the motor response as withdrawal (4) and the verbal response as inappropriate (3).","A total of 11 would score the motor response as withdrawal (4), but pushing the stimulus away is localizing (5).","A total of 13 would score the eyes as spontaneous (4), but they opened only to speech (3)."],
"Eye opening to speech scores 3, attempting to remove chest pressure is localizing pain (5), and confused, disoriented conversation scores 4, for a total of 12. Scoring the arm movement as withdrawal (4) would give 11.");
add("mock-b-054","ch27-cranial","To test the spinal accessory nerve, the examiner asks the patient to turn the head to the left against the examiner's hand. Which muscle should the examiner watch contract?",
["Left sternocleidomastoid","Right trapezius","Right sternocleidomastoid","Left trapezius"],2,
["The examiner observes the sternocleidomastoid opposite to the direction of head turning.","The trapezius is tested with a shoulder shrug, not head turning.","","The trapezius is tested with a shoulder shrug, not head turning."],
"During head turning against resistance, the examiner observes contraction of the opposite sternocleidomastoid, so turning left engages the right muscle. The trapezius is assessed separately with a shoulder shrug.");
add("mock-b-055","ch27-cranial","An alert patient has anisocoria that becomes more obvious in a dark room. Both pupils constrict normally to light, but one pupil dilates poorly. Which condition does this pattern suggest?",
["Oculomotor nerve (CN III) palsy","Transtentorial herniation","Intracranial aneurysm","Horner syndrome"],3,
["In CN III palsy the large pupil reacts poorly to light and anisocoria worsens in light.","Herniation is considered for a poorly reactive large pupil in a comatose patient.","An aneurysm is considered when an awake patient has a large pupil that reacts poorly to light.",""],
"Anisocoria that worsens in darkness with normal light reactions but poor dilation of one pupil suggests Horner syndrome from loss of sympathetic innervation. When anisocoria worsens in light and the large pupil reacts poorly, CN III palsy is the concern.");
add("mock-b-056","ch27-headtypes","A 62-year-old has sudden shocklike jabs of severe pain in the right cheek and jaw. Each jab lasts seconds and is set off by chewing or brushing the teeth. Which diagnosis best fits?",
["Trigeminal neuralgia","Cluster headache","Headache from sinusitis","Giant cell arteritis"],0,
["","Cluster pain is behind or around the eye, lasts 15 minutes to 3 hours, and has autonomic symptoms.","Sinus headache is aching or throbbing for hours with nasal congestion and local tenderness.","Giant cell arteritis gives persistent throbbing pain near the temporal artery, not seconds-long jabs."],
"Table 27-5 describes trigeminal neuralgia as shocklike, stabbing pain in the cheek, jaws, lips, or gums, with jabs lasting seconds and triggered by chewing, talking, or brushing teeth. Cluster headache is also stabbing but is centered on the eye and lasts much longer.");
add("mock-b-057","ch27-reflex","While the examiner passively extends a patient's elbow, resistance rises sharply when the arm is moved quickly and is greatest near the end of the range. Slow movement meets less resistance. Disease of which system does this pattern of tone most suggest?",
["Corticospinal tract","Basal ganglia","Cerebellum","Peripheral nerves"],0,
["","Basal ganglia disease causes rigidity, increased tone that stays constant through the range and is not velocity-dependent.","Cerebellar disease decreases muscle tone rather than increasing it.","Peripheral nerve disease causes decreased tone (hypotonia), not increased tone."],
"Increased tone that is velocity-dependent and worsens at the extremes of range is spasticity, which Box 27-14 links to central diseases affecting the corticospinal tract. Rigidity from basal ganglia disease also increases tone but stays constant regardless of speed.");
add("mock-b-058","ch27-seizure","A patient develops stiffening and then jerking of the left hand that spreads up the left arm and into the left side of the face. The patient stays fully aware throughout. Which seizure type is this?",
["Generalized tonic-clonic seizure","Focal seizure with impaired consciousness","Myoclonic seizure","Jacksonian focal seizure"],3,
["A tonic-clonic seizure begins with sudden loss of consciousness.","That type impairs consciousness and often includes automatisms, but awareness is preserved here.","Myoclonic seizures are sudden brief jerks of the trunk or limbs without a spreading march.",""],
"Table 27-8 describes Jacksonian seizures as tonic then clonic movements that start unilaterally in the hand, foot, or face and spread on the same side with normal consciousness. A generalized tonic-clonic seizure starts with loss of consciousness.");
add("mock-b-059","ch27-tremor","A 40-year-old whose father had Huntington disease has brief, rapid, jerky, irregular movements of the face and hands. They are unpredictable and seldom repeat in the same way. Which movement disorder is this?",
["Tics","Chorea","Athetosis","Resting tremor"],1,
["Tics are repetitive, stereotyped movements, whereas these seldom repeat themselves.","","Athetoid movements are slower, twisting, and writhing, with larger amplitude.","A resting tremor is rhythmic and oscillatory, not irregular and unpredictable."],
"Table 27-9 describes choreiform movements as brief, rapid, jerky, irregular, and unpredictable, and unlike tics they seldom repeat; Huntington disease is a listed cause. Tics are the closest competitor but are stereotyped and repetitive.");
add("mock-b-060","ch28-child-face","A 6-year-old has ear pain. Gently moving the pinna before inserting the otoscope causes sharp pain, and the area over the mastoid bone is not red or swollen. Which diagnosis is most likely?",
["Acute otitis media","Acute mastoiditis","Otitis media with effusion","Otitis externa"],3,
["Pinna movement elicits pain in otitis externa but not in otitis media.","Acute mastoiditis makes the area over the mastoid red, swollen, and tender, which is absent here.","Otitis media with effusion shows fluid behind a retracted membrane and is not marked by pain on moving the pinna.",""],
"Pain on moving the pinna points to otitis externa, and the text specifies this sign is absent in otitis media. A normal mastoid area argues against acute mastoiditis.");
add("mock-b-061","ch28-child-head","Shortly after a vaginal birth, a newborn has soft scalp edema over the vertex that extends across the suture lines. Which finding is most likely?",
["Caput succedaneum","Cephalohematoma","Craniosynostosis","Hydrocephalus"],0,
["","A cephalohematoma is subperiosteal blood that does not cross a suture and appears within the first 24 hours rather than at birth.","Craniosynostosis is premature suture closure causing abnormal skull shape, not scalp edema.","Hydrocephalus presents with a bulging anterior fontanelle and possibly a setting sun sign, not birth-related scalp edema."],
"Scalp edema from birth pressure that crosses sutures is caput succedaneum, which resolves in 1 to 2 days. A cephalohematoma is confined by the sutures because the blood lies beneath the periosteum.");
add("mock-b-062","ch28-child-murmur","A newborn has no murmur at the birth examination. At a 10-day visit, a harsh pansystolic murmur is heard at the lower left sternal border. Which physiologic change best explains why the murmur appeared after birth?",
["Flow through a narrowed valve or outflow tract","Postnatal fall in pulmonary vascular resistance","Pressure gradient already present between chambers","Increased right ventricular compliance with growth"],1,
["Obstructive lesions such as pulmonic or aortic stenosis are audible at birth because they do not depend on resistance changes.","","Murmurs from existing pressure gradients, such as atrioventricular valve regurgitation, are audible at birth.","Growth-related compliance change explains the atrial septal defect murmur, which often appears at 1 year or later."],
"A harsh pansystolic lower left sternal border murmur fits a ventricular septal defect, whose murmur depends on the postnatal drop in pulmonary vascular resistance and may appear 7 to 10 days after birth. Obstructive and pressure-gradient murmurs are already audible at birth.");
add("mock-b-063","ch28-child-resp","A 3-week-old infant has a respiratory rate of 70 breaths/min while calm, but there is no nasal flaring, grunting, or retractions. Which cause does this pattern most suggest?",
["Pneumonia","Croup","Cardiac disease","Bronchiolitis"],2,
["Pneumonia is a pulmonary disease, and pulmonary diseases increase respiratory effort.","Croup causes stridor and prolonged inspiration from upper airway obstruction.","","Bronchiolitis can cause nasal flaring, grunting, and tachypnea, reflecting increased work of breathing."],
"Tachypnea without increased work of breathing, called peaceful tachypnea, suggests cardiac disease. Pulmonary causes such as pneumonia or bronchiolitis raise respiratory effort, producing signs like flaring, grunting, or retractions.");
add("mock-b-064","ch29-preg-head","A patient at 9 weeks' gestation has had daily nausea and vomiting. The patient's prepregnancy weight was 70 kg, and the current weight is 65.5 kg. How should this weight change be interpreted?",
["Expected, since most pregnant persons have nausea","Excessive, consistent with hyperemesis gravidarum","Expected from the rise in basal metabolic rate","Acceptable unless the loss exceeds 10 percent"],1,
["Nausea affects up to 75% of pregnant persons, but weight loss above 5% of prepregnancy weight is not expected.","","The 15% to 20% rise in basal metabolic rate increases energy needs; it does not make a loss above 5% acceptable.","The threshold for excessive loss is more than 5% of prepregnancy weight, not 10%."],
"A 4.5 kg loss from 70 kg is about 6.4%, which exceeds the 5% threshold that defines hyperemesis gravidarum. Ordinary nausea of pregnancy is common, but weight loss beyond 5% is considered excessive.");
add("mock-b-065","ch29-preg-heart","A patient at 34 weeks' gestation becomes dizzy and feels faint several minutes after lying flat on the examination table. Which mechanism best explains these symptoms?",
["Uterine compression of the vena cava reducing venous return","Diaphragmatic elevation reducing functional residual capacity","Progesterone-driven respiratory alkalosis with dyspnea","Physiologic anemia from plasma volume expansion"],0,
["","Diaphragmatic elevation contributes to the sensation of dyspnea, not to faintness provoked by lying flat.","Progesterone increases ventilation and causes respiratory alkalosis, which does not explain symptoms triggered by the supine position.","Physiologic anemia reflects hemodilution and does not account for symptoms provoked by lying supine."],
"Late in pregnancy, lying flat lets the gravid uterus compress the vena cava and aorta, impairing venous return and causing supine hypotension. A semi-sitting position or slight leftward tilt prevents it; the respiratory changes cause dyspnea rather than position-dependent faintness.");
add("mock-b-066","ch30-geriatric","A 79-year-old has new atrial fibrillation, weight loss, and fatigue but denies heat intolerance, palpitations, or sweating. Which condition presenting atypically best fits this picture?",
["Hypothyroidism","Depression","Myocardial infarction","Hyperthyroidism"],3,
["Hypothyroidism in older adults causes subtle symptoms easily attributed to aging, not atrial fibrillation with weight loss.","Atypical depression in older adults is described as loss of interest, weight loss, or neglect of personal care, without atrial fibrillation.","Atypical myocardial infarction presents with fatigue, dyspnea, syncope, or confusion rather than weight loss with atrial fibrillation.",""],
"Older adults with hyperthyroidism may lack heat intolerance, palpitations, and sweating and instead show atrial fibrillation, weight loss, or fatigue. Depression can also cause weight loss, but the new atrial fibrillation points to the thyroid.");
add("mock-b-067","ch30-geriatric","While reviewing function in an 83-year-old, which task is classified as a basic activity of daily living rather than an instrumental activity?",
["Using the telephone","Transferring","Doing laundry","Taking medicine"],1,
["Using the telephone is an instrumental activity of daily living.","","Doing laundry is an instrumental activity of daily living.","Taking medicine is listed among the instrumental activities of daily living."],
"The six basic ADLs are bathing, dressing, toileting, transferring, maintaining continence, and feeding. Taking medicine may seem like basic self-care, but it is listed among the instrumental activities.");
add("mock-b-068","ch30-older-heent","A 60-year-old can read distant road signs clearly but must hold a menu at arm's length to read it. Which age-related change explains this?",
["Stiffening of the lens so near images focus behind the retina","Optic neuropathy producing an increased cup-to-disc ratio","Drusen deposits in the central macula","Atrophy of periorbital fat producing sunken eyes"],0,
["","An increased cup-to-disc ratio signals glaucoma, which causes peripheral and central vision loss rather than a near-focusing deficit.","Central drusen indicate macular degeneration, which causes poor central vision rather than a near-focusing deficit.","Periorbital fat atrophy is a structural change around the eye that does not affect focusing."],
"In presbyopia, the aging lens stiffens and can no longer converge rays from near objects on the retina, so they focus behind it while distance vision is preserved. Glaucoma cupping and macular drusen cause vision loss but not a selective near-vision problem.");
add("mock-b-069","ch11-delirium","On postoperative day 2, an 84-year-old is quiet and somnolent, drifts off mid-sentence, and cannot keep attention on questions. The family says this began yesterday and comes and goes. A staff member says delirium is unlikely because the patient is calm. Which response is most accurate?",
["Calm behavior points to dementia rather than delirium","Delirium can present with abnormally decreased activity","Delirium requires agitation or hypervigilance","Behavior is typically normal in delirium"],1,
["Dementia has an insidious onset with attention usually unaffected until late, unlike this acute fluctuating picture.","","Delirium activity may be abnormally increased or decreased, so agitation is not required.","Delirium behavior is often abnormal, either decreased or increased."],
"In delirium, activity is often abnormally decreased (somnolence) or increased (agitation), so a calm, somnolent patient with acute fluctuating inattention can be delirious. Dementia does not explain an onset over one day with fluctuating attention.");
add("mock-b-070","ch11-delirium","A nurse practitioner wants a quick bedside instrument to screen at-risk hospitalized older adults for delirium. Which tool is recommended for this purpose?",
["Montreal Cognitive Assessment (MoCA)","Mini-Cog","St. Louis University Mental Status Exam","Confusion Assessment Method (CAM)"],3,
["The MoCA is listed as a recommended screening test for dementia.","The Mini-Cog is listed as a recommended screening test for dementia.","The SLUMS is listed as a recommended screening test for dementia.",""],
"The CAM is recommended for screening at-risk patients and can quickly and accurately detect delirium at the bedside. The MoCA, Mini-Cog, and SLUMS are the recommended dementia screening tests.");
root.L.ITEMS.forEach(function(it){if(it.id.indexOf('mock-b-')===0)it.pool='x';});
})(typeof window!=='undefined'?window:globalThis);
